// Reads the Seerah map art straight from design-assets/seerah/ and writes the SVG sources as strings in
// src/features/seerah/art/seerah-art.generated.ts, so the app renders them with SvgXml (no SVG transformer in Metro).
// Run from apps/mobile: npm run assets:seerah. The art is the design's; never edit the generated file by hand.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, '../../../design-assets/seerah');
const out = join(here, '../src/features/seerah/art/seerah-art.generated.ts');
const levels = ['region', 'makkah', 'madinah'];

const entries = levels.map((level) => {
  const pair = {};
  for (const [theme, suffix] of [['light', ''], ['dark', '-dark']]) {
    const file = `map-${level}${suffix}.svg`;
    pair[theme] = readFileSync(join(source, file), 'utf8').trim();
  }
  return `  ${level}: {\n    light: ${JSON.stringify(pair.light)},\n    dark: ${JSON.stringify(pair.dark)},\n  },`;
});

writeFileSync(
  out,
  `// Generated by scripts/generate-seerah-art.mjs from design-assets/seerah/. Do not edit.\n\nexport const seerahArt = {\n${entries.join('\n')}\n} as const;\n\nexport type SeerahArtLevel = keyof typeof seerahArt;\n`,
);
console.log(`wrote ${out}`);
